  ('453f0235-c5cf-5472-8f47-5a6b6b022fc6', null, (select id from public.skills where slug = 'read-g8-literary-structure-pov'), null, 'hard',
   $q$Compare how the first two episodes end with how the third ends. What does this difference in pacing show?$q$, $q$[{"text":"The quick tries fail within one day, but the slow method spans many days and succeeds.","is_correct":true},{"text":"The third try ends faster than the others, showing the old beaver knew a trick.","is_correct":false,"misconception_token":"reverses-structure"},{"text":"All three tries take the same amount of time, so speed did not matter to the result.","is_correct":false,"misconception_token":"misreads-pacing"},{"text":"The first try takes the longest, showing that thick branches were the best choice.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$The quick tries fail within one day, but the slow method spans many days and succeeds.$q$, $q$The first two attempts end "by noon" and "by evening," while the third stretches across "every day" until the frost, which matches the moral about steady work. Nothing in the old beaver's method is fast.$q$, 'draft', '2366d6b8-56e8-5831-85db-6109c8562e2c')
